//! 🌱️ A nested pending row keeps its original identity and copies only the genuine parent's required context.
use super::*;
use flow::{FlowTextCopyWork,invocation_publication::{FlowInvocationOrigin,FlowInvocationOriginLease}};
#[derive(RetireOwned)]
struct Fields{pending:Option<flow::neural::PendingExtensionEval>,texts:[Option<String>;4],origin:Option<FlowInvocationOrigin>,output:Option<FlowInvocationOriginLease>}
pub(crate) struct FlowPendingOriginWork{fields:ManuallyDrop<Option<Fields>>,text:Option<FlowTextCopyWork>,retirement:RetainedCloneClose,binding:Option<(OriginalSourceBinding,usize)>,rank:usize,phase:u8,closing:bool}
pub(super) fn paid(cx:&mut StepContext<'_>,bytes:usize)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()};if cx.should_yield()||cx.is_cancelled()||!cx.retained_work_can_enter(d){return Ok(false)}cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;Ok(true)}
impl FlowPendingOriginWork{
 pub(crate) fn new(pending:flow::neural::PendingExtensionEval)->Self{Self{fields:ManuallyDrop::new(Some(Fields{pending:Some(pending),texts:[None,None,None,None],origin:None,output:None})),text:None,retirement:Default::default(),binding:None,rank:0,phase:0,closing:false}}
 pub(crate) fn step(&mut self,parent:&FlowInvocationOrigin,cx:&mut StepContext<'_>)->Result<Option<FlowInvocationOriginLease>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.retained_progress(),cx.original_total_fuel_remaining());if let Some(value)=self.once(parent,cx)?{return Ok(Some(value))}if cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.original_total_fuel_remaining()){break}}Ok(None)}
 fn once(&mut self,parent:&FlowInvocationOrigin,cx:&mut StepContext<'_>)->Result<Option<FlowInvocationOriginLease>,OriginalTurnFailure>{
  let binding=(OriginalSourceBinding::borrow(cx),parent as*const _ as usize);if self.closing||self.binding.is_some_and(|original|original!=binding){return Err(invalid().into())}if cx.should_yield()||cx.is_cancelled(){return Ok(None)}
  match self.phase{
   0=>if paid(cx,size_of::<Option<(OriginalSourceBinding,usize)>>()+size_of::<FlowTextCopyWork>())?{self.binding=Some(binding);self.text=Some(FlowTextCopyWork::new());self.phase=1},
   1=>{let source=match self.rank{0=>&parent.window_id,1=>&parent.window_kind_id,2=>&parent.dependency_json,3=>&parent.operator_version,_=>return Err(invalid().into())};let text=self.text.as_mut().ok_or_else(invalid)?;if !text.ready(){text.advance(source,cx)?;}else if text.take_into(&mut self.fields.as_mut().ok_or_else(invalid)?.texts[self.rank],cx)?{text.begin_close();self.phase=2}},
   2=>{let text=self.text.as_mut().ok_or_else(invalid)?;if text.terminal_is_empty(){if paid(cx,size_of::<FlowTextCopyWork>())?{self.text=None;self.rank+=1;self.phase=if self.rank==4{3}else{0}}}else{let d=text.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|text.close_step(g))?;}},
   3=>if paid(cx,2*size_of::<FlowInvocationOrigin>()+size_of::<flow::neural::PendingExtensionEval>())?{let fields=self.fields.as_mut().ok_or_else(invalid)?;let pending=fields.pending.take().ok_or_else(invalid)?;fields.origin=Some(FlowInvocationOrigin{window_id:fields.texts[0].take().ok_or_else(invalid)?,window_kind_id:fields.texts[1].take().ok_or_else(invalid)?,dependency_json:fields.texts[2].take().ok_or_else(invalid)?,operator_version:fields.texts[3].take().ok_or_else(invalid)?,neuron_id:pending.neuron_id,extension_id:pending.extension_id,operator_id:pending.operator_id,node_hash:pending.node_hash,input_json:pending.input_json,outer_node_hash:Some(parent.node_hash),preview_source:None});self.phase=4},
   4=>{let d=RetirementDemand{capacity_bytes:FlowInvocationOriginLease::allocation_bytes(),depth:1,..Default::default()};if !cx.retained_work_can_enter(d){return Ok(None)}let fields=self.fields.as_mut().ok_or_else(invalid)?;let origin=fields.origin.take().ok_or_else(invalid)?;let turn=FlowInvocationOriginLease::admit(origin,RetainedCloneGrant{maximum_items:1,..cx.retained_grant()});let result=match turn.result{Ok((output,p))=>{fields.output=Some(output);self.phase=5;Ok(RetainedCloneStep::Complete(p))},Err((error,origin))=>{fields.origin=Some(origin);Err(error)}};semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;},
   5=>if paid(cx,2*size_of::<Option<FlowInvocationOriginLease>>())?{self.phase=6;return Ok(self.fields.as_mut().ok_or_else(invalid)?.output.take())},
   _=>return Err(invalid().into())
  }Ok(None)
 }
 pub(crate) fn restore_output(&mut self,value:FlowInvocationOriginLease){assert_eq!(self.phase,6);self.fields.as_mut().expect("original pending context").output=Some(value);self.phase=5}
 pub(crate) fn begin_close(&mut self){self.closing=true;if let Some(text)=self.text.as_mut(){text.begin_close()}}
 pub(crate) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(text)=self.text.as_ref(){return if text.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<FlowTextCopyWork>(),depth:1,..Default::default()})}else{text.close_demands(body)}}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.fields.is_some(){return self.retirement.next_owner_demands::<Fields>(true,&None,body)}Ok(RetirementDemand{copy_bytes:size_of::<Option<(OriginalSourceBinding,usize)>>(),depth:usize::from(self.binding.is_some()),..Default::default()})}
 pub(crate) fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<Close,OriginalTurnFailure>{if !self.closing||self.binding.is_some_and(|binding|!binding.0.matches(cx)){return Err(invalid().into())}if let Some(text)=self.text.as_mut(){if !text.terminal_is_empty(){let d=text.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|text.close_step(g))?;return Ok(Close::Pending{progress:step.progress()})}let d=RetirementDemand{copy_bytes:size_of::<FlowTextCopyWork>(),depth:1,..Default::default()};if cx.retirement_should_yield()||!cx.retained_work_can_enter(d){return Ok(Close::Blocked)}self.text=None;cx.consume_fuel(1);let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};cx.consume_retained(p)?;return Ok(Close::Pending{progress:p})}
  let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if self.fields.is_some(){let turn=self.retirement.begin_granted(&mut self.fields,g);return RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}if self.binding.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.binding=None;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(if self.terminal_is_empty(){Close::Complete{progress:step.progress()}}else{Close::Pending{progress:step.progress()}})}
 pub(crate) fn terminal_is_empty(&self)->bool{self.closing&&self.text.is_none()&&self.fields.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for FlowPendingOriginWork{fn drop(&mut self){assert!(self.terminal_is_empty(),"original pending row and copied parent context require paid terminal closure");unsafe{ManuallyDrop::drop(&mut self.fields)}}}
